#include "soft_renderer.hpp"
#include "core_menu.hpp"
#include <cstdio>
#include <stdexcept>
using namespace soft;
static void check(bool ok,const char* msg){if(!ok)throw std::runtime_error(msg);}
static void rect(Renderer& r,float l,float t,float right,float bottom,unsigned color,unsigned alpha,unsigned blend,bool zWrite=false){ScreenVertex v[4]={{l,t,2,0,0,float(color>>16),float((color>>8)&255),float(color&255),float(alpha),0},{right,t,2,0,0,float(color>>16),float((color>>8)&255),float(color&255),float(alpha),0},{l,bottom,2,0,0,float(color>>16),float((color>>8)&255),float(color&255),float(alpha),0},{right,bottom,2,0,0,float(color>>16),float((color>>8)&255),float(color&255),float(alpha),0}};ScreenState s;s.blend=blend;s.screenDepth=true;s.zWrite=zWrite;s.zTest=zWrite;ScreenVertex a[3]={v[0],v[1],v[2]},b[3]={v[2],v[1],v[3]};r.screenTriangle(a,nullptr,s);r.screenTriangle(b,nullptr,s);}
int main(){try{CoreMenu menu;menu.toggle();for(int i=0;i<9;++i)menu.key(CoreKey::Down);check(menu.settings.hudWidth()==640,"old defaults preserved");menu.key(CoreKey::Right);check(menu.settings.hudWidth()==240&&CoreSettings::valid(menu.settings.bits),"new HUD choice");menu.key(CoreKey::Right);check(menu.settings.hudWidth()==320,"three HUD sizes cycle");menu.key(CoreKey::Left);check(menu.settings.hudWidth()==240,"HUD reverse cycle");check(!CoreSettings::valid(1536),"conflicting HUD modes rejected");
 Renderer r;Camera c;c.position={0,0,0};r.clear(rgb(0,0,255));Vec3 tri[3]={{-.5f,-.5f,2},{.5f,-.5f,2},{0,.5f,2}};r.triangle(tri,rgb(255,255,0),c);auto world=r.pixels();r.beginHud(240);check(r.pixels()==world,"empty HUD preserves detailed world exactly");rect(r,4,4,80,80,0xff0000,128,1);auto p=r.pixels();check(p[30*320+30]==rgb(128,0,127),"premultiplied layer blends with original world");check(p[120*320+160]==world[120*320+160],"world triangle untouched outside HUD");rect(r,4,4,80,80,0x00ff00,255,0);check(r.pixels()[30*320+30]==rgb(0,255,0),"opaque UI replaces underlying overlay");
 r.beginUi(true);check(r.outputWidth()==640&&r.pixels()[60*640+60]==rgb(0,255,0),"native menu transition keeps composited HUD");r.clear(0);check(r.outputWidth()==320&&r.pixels().size()==320*240,"next world frame restores buffers");
 r.clear(rgb(0,0,255));r.beginHud(240);rect(r,0,0,100,100,0xff0000,255,0);rect(r,0,0,100,100,0x00ff00,128,2);check(r.stats().hudFallbacks==1&&r.pixels()[30*320+30]==rgb(255,128,0),"unusual blend safely falls back with correct compositing");
 // Equal nominal screen depth must be independent of triangle barycentric drift.
 for(int i=0;i<30;++i){r.clear(0);r.beginUi(i%2);rect(r,1.13f,2.37f,290.93f,210.71f,0x000000,255,0,true);rect(r,20.17f+i*.01f,30.43f,250.91f,190.13f,0x00aaff,255,0,true);unsigned w=r.outputWidth(),m=w/320;check(r.pixels()[100*m*w+100*m]==rgb(0,170,255),"glyph fill cannot be hidden by equal-depth shadow");}
 puts("PASS HUD 240 overlay, unchanged world, alpha, fallback, menu transition, settings, equal screen depth");return 0;}catch(const std::exception& e){fprintf(stderr,"%s\n",e.what());return 1;}}
